def comb3(m: int) -> int:
    if m < 3:
        return 0
    return m * (m - 1) * (m - 2) // 6

def expected_via_residues(n: int) -> int:
    cnt0 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 0)
    cnt1 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 1)
    cnt2 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 2)
    assert cnt2 == 0
    assert cnt0 + cnt1 == n
    return comb3(cnt0) + comb3(cnt1)

